-- Pagamento das 4 pagas: lançamento conjunto do pagador, 1 parcela no vencimento com o
-- valor pago. Luz, Gás e Diarista por Ana (Pix da Ana); Água por Leandro (Pix Nubank).
insert into app.lancamento (id, lar_id, dono_id, tipo, escopo, categoria_id, descricao, valor_total_centavos, num_parcelas)
select v.id::uuid, m.lar_id, m.id, 'despesa', 'conjunto', f.categoria_id, f.descricao, v.valor, 1
from (values
  ('00000000-0000-4000-8000-000000000530', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000703', 18740),
  ('00000000-0000-4000-8000-000000000531', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000706', 9510),
  ('00000000-0000-4000-8000-000000000532', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000707', 5000),
  ('00000000-0000-4000-8000-000000000533', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000705', 10000)
) as v(id, dono, fixa, valor)
join app.membro m on m.id = v.dono::uuid
join app.despesa_fixa f on f.id = v.fixa::uuid;

insert into app.lancamento_pagamento (lancamento_id, lar_id, dono_id, forma_pagamento_id, conta_id, data_operacao)
select l.id, l.lar_id, l.dono_id, v.forma::uuid, v.conta::uuid, o.vencimento
from (values
  ('00000000-0000-4000-8000-000000000530', '00000000-0000-4000-8000-000000000803', '00000000-0000-4000-8000-000000000311', '00000000-0000-4000-8000-000000000211'),
  ('00000000-0000-4000-8000-000000000531', '00000000-0000-4000-8000-000000000806', '00000000-0000-4000-8000-000000000301', '00000000-0000-4000-8000-000000000201'),
  ('00000000-0000-4000-8000-000000000532', '00000000-0000-4000-8000-000000000807', '00000000-0000-4000-8000-000000000311', '00000000-0000-4000-8000-000000000211'),
  ('00000000-0000-4000-8000-000000000533', '00000000-0000-4000-8000-000000000805', '00000000-0000-4000-8000-000000000311', '00000000-0000-4000-8000-000000000211')
) as v(lancamento, ocorrencia, forma, conta)
join app.lancamento l on l.id = v.lancamento::uuid
join app.ocorrencia_fixa o on o.id = v.ocorrencia::uuid;

insert into app.parcela (id, lancamento_id, lar_id, escopo, dono_id, numero, valor_centavos, data)
select v.id::uuid, l.id, l.lar_id, l.escopo, l.dono_id, 1, l.valor_total_centavos, o.vencimento
from (values
  ('00000000-0000-4000-8000-000000000640', '00000000-0000-4000-8000-000000000530', '00000000-0000-4000-8000-000000000803'),
  ('00000000-0000-4000-8000-000000000641', '00000000-0000-4000-8000-000000000531', '00000000-0000-4000-8000-000000000806'),
  ('00000000-0000-4000-8000-000000000642', '00000000-0000-4000-8000-000000000532', '00000000-0000-4000-8000-000000000807'),
  ('00000000-0000-4000-8000-000000000643', '00000000-0000-4000-8000-000000000533', '00000000-0000-4000-8000-000000000805')
) as v(id, lancamento, ocorrencia)
join app.lancamento l on l.id = v.lancamento::uuid
join app.ocorrencia_fixa o on o.id = v.ocorrencia::uuid;

update app.ocorrencia_fixa o set lancamento_id = v.lancamento::uuid
from (values
  ('00000000-0000-4000-8000-000000000803', '00000000-0000-4000-8000-000000000530'),
  ('00000000-0000-4000-8000-000000000806', '00000000-0000-4000-8000-000000000531'),
  ('00000000-0000-4000-8000-000000000807', '00000000-0000-4000-8000-000000000532'),
  ('00000000-0000-4000-8000-000000000805', '00000000-0000-4000-8000-000000000533')
) as v(ocorrencia, lancamento)
where o.id = v.ocorrencia::uuid;
